import Foundation

struct Expense {
    let title: String
    let amount: Decimal
    let category: String
}

func total(for expenses: [Expense], category: String? = nil) -> Decimal {
    let selected = category?.trimmingCharacters(in: .whitespacesAndNewlines)
    return expenses.filter { expense in
        guard let selected else { return true }
        return expense.category.localizedCaseInsensitiveCompare(selected) == .orderedSame
    }.reduce(Decimal.zero) { $0 + $1.amount }
}

let expenses = [Expense(title: "Notebook", amount: 120, category: "Study"), Expense(title: "Bus", amount: 35, category: "Travel")]
print("All: \(total(for: expenses))")
print("Study: \(total(for: expenses, category: "Study"))")
